/// <summary>
/// Service class for the intercompany PO vendor invoice.
/// </summary>
public class METIntercompanyPOVendInvoiceService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// Process method for PO fulfillment.
/// </summary>
/// <param name = "_contract">METIntercompanyPOFulfillmentContract</param>
public void processIntercompanyPOFulfillment(METIntercompanyPOFulfillmentContract _contract)
{
    Query       query       = new Query(SysOperationHelper::base64Decode(_contract.parmPackedQuery()));
    QueryRun    queryRun    = new QueryRun(query);

    while (queryRun.next())
    {
        SalesId                 metReplenishmentSOReference;
        PurchLine               purchLine;
        PurchTable              purchTable  = queryRun.get(tableNum(PurchTable));
        CustInvoiceJour         custInvoiceJour;
        VendInvoiceJour         vendInvoiceJour;
        VendPackingSlipJour     vendPackingSlipJour;
        VendInvoiceInfoTable    vendInvoiceInfoTableLoc;
        VendInvoiceInfoLine     vendInvoiceInfoLine;
        VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;
        SalesLine               salesLine;

        while select purchLine
            where purchLine.PurchId == purchTable.PurchId
            && purchLine.IsDeleted == NoYes::No
        {
            metReplenishmentSOReference = purchLine.METReplenishmentSOReference;

            changecompany(purchTable.InterCompanyCompanyId)
            {   
                salesLine = this.findSalesLine(purchLine);

                if (salesLine.SalesStatus == SalesStatus::Invoiced)
                {
                    custInvoiceJour = this.findCustInvoiceJour(salesLine);
                }
            }

            if (custInvoiceJour)
            {
                this.createPendingVendorInvoice(purchLine, salesLine);
            }
        }
    }
}

/// <summary>
///Process method for the PO replenishment.
/// </summary>
/// <param name = "_contract">METIntercompanyPOReplenishmentContract</param>
public void processIntercompanyPOReplenishment(METIntercompanyPOReplenishmentContract _contract)
{
    Query       query       = new Query(SysOperationHelper::base64Decode(_contract.parmPackedQuery()));
    QueryRun    queryRun    = new QueryRun(query);

    while (queryRun.next())
    {
        SalesId                 metReplenishmentSOReference;
        PurchLine               purchLine;
        PurchTable              purchTable = queryRun.get(tableNum(PurchTable));
        CustInvoiceJour         custInvoiceJour;
        VendInvoiceJour         vendInvoiceJour;
        VendPackingSlipJour     vendPackingSlipJour;
        VendInvoiceInfoTable    vendInvoiceInfoTableLoc;
        VendInvoiceInfoLine     vendInvoiceInfoLine;
        VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;
        SalesLine               salesLine;

        if ((purchTable.METIntercompanyTransferReplenishment == NoYes::Yes || purchTable.InterCompanyOrder == NoYes::Yes)
            && purchTable.PurchStatus != PurchStatus::Invoiced)
        {
            while select purchLine
                where purchLine.PurchId == purchTable.PurchId
                && purchLine.IsDeleted == NoYes::No
            {
                metReplenishmentSOReference = purchLine.METReplenishmentSOReference;

                changecompany(purchTable.InterCompanyCompanyId)
                {
                    salesLine = this.findSalesLine(purchLine);

                    if (salesLine.SalesStatus == SalesStatus::Invoiced)
                    {
                        custInvoiceJour = this.findCustInvoiceJour(salesLine);
                    }
                }
                if (custInvoiceJour)
                {
                    this.createPendingVendorInvoice(purchLine, salesLine);
                }
            }
        }
    }
}

/// <summary>
/// Finds the customer invoice journal for the given sales line.
/// </summary>
/// <param name="_salesLine">The sales line to find the invoice journal for.</param>
/// <returns>The related CustInvoiceJour record, or null if not found.</returns>
public CustInvoiceJour findCustInvoiceJour(SalesLine _salesLine)
{
    CustInvoiceJour         custInvoiceJour = null;
    CustInvoiceTrans        custInvoiceTrans;
    InventDim               salesInventDim, invoiceTransInventDim;

    salesInventDim = InventDim::find(_salesLine.InventDimId);

    select firstonly custInvoiceTrans
        where custInvoiceTrans.SalesId == _salesLine.SalesId
            && custInvoiceTrans.ItemId == _salesLine.ItemId
            && custInvoiceTrans.SalesUnit == _salesLine.SalesUnit
        join invoiceTransInventDim
        where  invoiceTransInventDim.inventBatchId == salesInventDim.inventBatchId
            && invoiceTransInventDim.InventSiteId == salesInventDim.InventSiteId
            && invoiceTransInventDim.InventLocationId == salesInventDim.InventLocationId
            && invoiceTransInventDim.wMSLocationId == salesInventDim.wMSLocationId;

    if (custInvoiceTrans.RecId)
    {
        custInvoiceJour = CustInvoiceJour::findRecId(custInvoiceTrans.ParentRecId);
    }

    return custInvoiceJour;
}

/// <summary>
/// Finds the sales line that matches the given purchase line based on replenishment reference and inventory dimensions.
/// </summary>
/// <param name="_purchline">The purchase line to match.</param>
/// <returns>The related SalesLine record, or null if not found.</returns>
public SalesLine findSalesLine(PurchLine _purchline)
{
    SalesLine               salesLine = null;
    InventDim               purchInventDim, salesInventDim;

    purchInventDim = InventDim::find(_purchline.InventDimId);

    select firstonly salesLine
                    where  salesLine.METReplenishmentPOReference == _purchline.PurchId
                        && salesLine.ItemId == _purchline.ItemId
                        && salesLine.SalesUnit == _purchline.PurchUnit
                    join salesInventDim
                    where  salesInventDim.inventBatchId == purchInventDim.inventBatchId
                        && salesInventDim.InventSiteId == purchInventDim.InventSiteId
                        && salesInventDim.InventLocationId == purchInventDim.InventLocationId
                        && salesInventDim.wMSLocationId == purchInventDim.wMSLocationId;

   return salesLine;
}

/// <summary>
/// Create the pending vendor invoice of the PO.
/// </summary>
/// <param name = "_purchTable">PurchTable</param>
/// <param name = "_invoiceQty">VendPackingSlipTrans</param>
/// <returns></returns>
public VendInvoiceInfoTable createPendingVendorInvoice(PurchLine _purchLine, SalesLine _salesLine)
{
    PurchTable              purchTable      = PurchTable::find(_purchLine.PurchId);
    CustInvoiceJour         custInvoiceJour = this.findCustInvoiceJour(_salesLine);
    CustInvoiceTrans        custInvoiceTrans;
    VendPackingSlipJour     vendPackingSlipJour;
    VendInvoiceInfoTable    vendInvoiceInfoTable;

    select firstonly custInvoiceTrans
        where custInvoiceTrans.ParentRecId == custInvoiceJour.RecId;

    vendInvoiceInfoTable.clear();
    vendInvoiceInfoTable.initValue();
    vendInvoiceInfoTable.initFromPurchTable(purchTable);

    vendInvoiceInfoTable.DocumentOrigin = DocumentOrigin::Manual;
    vendInvoiceInfoTable.defaultRow(null, null, true);

    vendInvoiceInfoTable.Num                    = custInvoiceJour.InvoiceId;
    vendInvoiceInfoTable.ParmId                 = formletterParmData::getNewParmId();
    vendInvoiceInfoTable.Payment                = VendTable::find(purchTable.InvoiceAccount).PaymTermId;
    vendInvoiceInfoTable.Approved               = NoYes::Yes;
    vendInvoiceInfoTable.TableRefId             = formletterParmData::getNewTableRefId();
    vendInvoiceInfoTable.Description            = _salesLine.SalesId;
    vendInvoiceInfoTable.MetImportGST           = custInvoiceTrans.TaxAmount;
    vendInvoiceInfoTable.DocumentDate           = vendInvoiceInfoTable.ReceivedDate;
    vendInvoiceInfoTable.METClaimInvoice        = NoYes::Yes;
    vendInvoiceInfoTable.MetImportAmount        = custInvoiceJour.InvoiceAmount;
    vendInvoiceInfoTable.LastMatchVariance      = LastMatchVarianceOptions::Unknown;

    if (vendInvoiceInfoTable.validateWrite())
    {
        vendInvoiceInfoTable.insert();

        VendInvoiceInfoSubTable vendInvoiceInfoSubTable;

        vendInvoiceInfoSubTable.clear();
        vendInvoiceInfoSubTable.initValue();
        vendInvoiceInfoSubTable.defaultRow();

        vendInvoiceInfoSubTable.ParmId          = vendInvoiceInfoTable.ParmId;
        vendInvoiceInfoSubTable.PurchName       = vendInvoiceInfoTable.PurchName;
        vendInvoiceInfoSubTable.TableRefId      = vendInvoiceInfoTable.TableRefId;
        vendInvoiceInfoSubTable.OrigPurchId     = vendInvoiceInfoTable.PurchId;

        vendInvoiceInfoSubTable.insert();
    }

    this.createPendingVendorInvoiceLines(vendInvoiceInfoTable, _purchLine, custInvoiceTrans);

    return vendInvoiceInfoTable;
}

/// <summary>
/// Create the pending vendor invoice lines of the PO.
/// </summary>
/// <param name = "_vendInvoiceInfoTable">VendInvoiceInfoTable</param>
/// <param name = "_purchLine">PurchLine</param>
/// <param name = "_invoiceQty">VendPackingSlipTrans</param>
public void createPendingVendorInvoiceLines(VendInvoiceInfoTable _vendInvoiceInfoTable,
                                            PurchLine _purchLine, CustInvoiceTrans _custInvoiceTrans)
{
    VendInvoiceInfoLine     vendInvoiceInfoLine;
    VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;

    vendInvoiceInfoLine.clear();
    vendInvoiceInfoLine.initValue();
    vendInvoiceInfoLine.initFromPurchLine(_purchLine);

    vendInvoiceInfoLine.ItemId              = _purchLine.ItemId;
    vendInvoiceInfoLine.ParmId              = _vendInvoiceInfoTable.ParmId;
    vendInvoiceInfoLine.PurchUnit           = _purchLine.PurchUnit;
    vendInvoiceInfoLine.InventNow           = _purchLine.PurchQty;
    vendInvoiceInfoLine.PurchPrice          = _purchLine.PurchPrice;
    vendInvoiceInfoLine.LineAmount          = _purchLine.LineAmount;
    vendInvoiceInfoLine.TableRefId          = _vendInvoiceInfoTable.TableRefId;
    vendInvoiceInfoLine.ReceiveNow          = _custInvoiceTrans.Qty;
    vendInvoiceInfoLine.PriceUnit           = _custInvoiceTrans.SalesPrice;
    vendInvoiceInfoLine.LineAmount          = _custInvoiceTrans.LineAmount;
    vendInvoiceInfoLine.OrigPurchId         = _purchLine.PurchId;
    vendInvoiceInfoLine.DeliveryName        = _vendInvoiceInfoTable.DeliveryName;
    vendInvoiceInfoLine.currencyCode        = _vendInvoiceInfoTable.CurrencyCode;
    vendInvoiceInfoLine.OrderAccount        = _vendInvoiceInfoTable.OrderAccount;
    vendInvoiceInfoLine.DocumentOrigin      = DocumentOrigin::Manual;
    vendInvoiceInfoLine.InvoiceAccount      = _vendInvoiceInfoTable.InvoiceAccount;

    vendInvoiceInfoLine.ProcurementCategory = EcoResProductCategory::findByItemIdCategoryHierarchyRole(_purchLine.ItemId, EcoResCategoryNamedHierarchyRole::Procurement).Category;

    vendInvoiceInfoLine.insert();

    if (vendInvoiceInfoLine.RecId)
    {
        vendInvoiceInfoSubLine.clear();
        vendInvoiceInfoSubLine.initValue();
        vendInvoiceInfoSubLine.defaultRow();

        vendInvoiceInfoSubLine.ParmId           =   vendInvoiceInfoLine.ParmId;
        vendInvoiceInfoSubLine.InventNow        =   vendInvoiceInfoLine.ReceiveNow;
        vendInvoiceInfoSubLine.ReceiveNow       =   vendInvoiceInfoLine.ReceiveNow;
        vendInvoiceInfoSubLine.LineRefRecId     =   vendInvoiceInfoLine.RecId;
        vendInvoiceInfoSubLine.LineRefRecId     =   vendInvoiceInfoLine.RecId;

        vendInvoiceInfoSubLine.insert();
    }
}

/// <summary>
/// Submit claim to workflow.
/// </summary>
/// <param name = "_claimInvoiceTable">VendInvoiceInfoTable</param>
private void submitClaimInvoiceToWorkflow(VendInvoiceInfoTable _claimInvoiceTable)
{
    if(_claimInvoiceTable && _claimInvoiceTable.existLine() && _claimInvoiceTable.canSubmitToWorkflow())
    {
        VendInvoiceHeaderWorkflow::submitToWorkflow(_claimInvoiceTable, _claimInvoiceTable.Description);
    }
}
